css:
.ob-toggle { display: inline-flex; border: 1px solid var(--border-alt); border-radius: 4px; overflow: hidden; }
.ob-toggle-btn {
  padding: 12px 22px; background: transparent; color: var(--text-dim); border: 0;
  font-family: 'JetBrains Mono', monospace; font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase;
}
.ob-toggle-btn.is-active { background: var(--accent); color: var(--bg); }

js:
export function initToggle(el, onChange) {
  const botoes = Array.prototype.slice.call(el.querySelectorAll('.ob-toggle-btn'));
  botoes.forEach(function (btn, i) {
    btn.addEventListener('click', function () {
      botoes.forEach(function (b) { b.classList.remove('is-active'); });
      btn.classList.add('is-active');
      if (onChange) onChange(i, btn.textContent);
    });
  });
}
